// 子音を日本語の「あかさたなはまら行」の並びに近づけた並び替え版
// ㅋ→か行の強い発音、ㅌ→た行の強い発音、ㅈㅊ→た行に近い音、ㅂㅍ→は行に近い音としてまとめて配置
