      "韓国語で物を数えるときは、固有数詞(하나・둘・셋…)の後ろに「助数詞(単位)」をつけます。人には「명」、物には「개」、年齢には「살」、飲み物には「잔」など、数える対象によって単位が変わります。ここで注意したいのが、助数詞の前では하나・둘・셋・넷が한・두・세・네という別の形に変わることです(하나→한 개ではなく한 개のように)。最初は「사람 한 명(人1人)」「커피 한 잔(コーヒー1杯)」のように、よく使う組み合わせを丸ごとフレーズとして覚えるのが近道です。",
    tip: "한 개・두 개・세 개…と「単位とセットの形」で口に出して覚えると定着しやすいです。",
